
export function levelState(current,n,replay=false){
 if(!Number.isInteger(n)||n<0||n>2)throw new RangeError('Unknown room');
 const s={...current,inventory:[...current.inventory],weights:[...current.weights],mirrors:[...current.mirrors],room:n};
 if(n>=1)s.balance=true;
 if(n===2){s.light=true;if(!s.wand&&!s.inventory.includes('prism'))s.inventory.push('prism');}
 if(replay){if(n===0){s.balance=false;s.weights=[];}
 if(n===1){s.light=false;s.mirrors=[0,0];}
 if(n===2){s.final=false;s.seenEnd=false;s.wand=false;s.inventory=s.inventory.filter(x=>!['wand','branch'].includes(x));if(!s.inventory.includes('prism'))s.inventory.push('prism');}}
 return s;
}
export function stickVector(x,y,radius){
 const d=Math.hypot(x,y);if(d<radius*.12)return {x:0,y:0};
 const scale=Math.min(1,d/radius)/d;return {x:x*scale,y:y*scale};
}

